def score(job_cpu, job_mem, free_cpu, free_mem):
    rem_cpu = free_cpu - job_cpu
    rem_mem = free_mem - job_mem
    # Penalize the bottleneck dimension heavily and penalize dimension imbalance
    return -(rem_cpu**2 + rem_mem**2 + 2 * max(rem_cpu, rem_mem)**2 + abs(rem_cpu - rem_mem) * 100)

